    options.exportPdf &&
    !options.scan &&
    !options.ci &&
    !options.setup &&
    !options.listDocs &&
    !options.clean &&
    !options.update &&
    !options.showConfig &&
    !options.key;
  if (exportOnly) {
    exportDocsAsPdf();
