export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let thresholdResults = null;
  let passed = true;

  if (thresholds && typeof thresholds === 'object' && Object.keys(thresholds).length > 0) {
    thresholdResults = [];
    for (const [metricId, minScore] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      if (!metric) {
        throw new Error(`Metric not found: ${metricId}`);
      }

      const score = metric.score;
      const metricPassed = score !== null && score >= minScore;
      if (!metricPassed) {
        passed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min: minScore,
        score: score,
        passed: metricPassed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults !== null) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

