import fs from 'fs';
import path from 'path';
import os from 'os';

// Simulate the core eval functions
const DEFAULT_METRICS = [
  function exactMatchMetric(outputs, references) {
    const outs = Array.isArray(outputs) ? outputs : [];
    const refs = Array.isArray(references) ? references : [];
    if (!outs.length || !refs.length || outs.length !== refs.length) {
      return {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: outs.length,
        matches: 0,
        details: 'Outputs and references must be non-empty arrays of equal length for exact match.'
      };
    }

    let matches = 0;
    const perSample = [];

    outs.forEach((output, index) => {
      const predicted = String(output).trim().toLowerCase();
      const expected = String(refs[index]).trim().toLowerCase();
      const match = predicted === expected;
      if (match) matches += 1;
      perSample.push({ index, match, predicted, expected });
    });

    return {
      id: 'exact_match',
      label: 'Exact Match',
      score: Number((matches / outs.length).toFixed(4)),
      total: outs.length,
      matches,
      samples: perSample
    };
  },
  function toxicityMetric(outputs) {
    const outs = Array.isArray(outputs) ? outputs : [];
    if (!outs.length) {
      return {
        id: 'toxicity',
        label: 'Toxicity (keyword scan)',
        score: null,
        total: 0,
        flagged: 0
      };
    }

    const bannedTerms = ['hate', 'kill', 'violence'];
    const flaggedSamples = [];

    outs.forEach((output, index) => {
      const text = String(output).toLowerCase();
      const hits = bannedTerms.filter((term) => text.includes(term));
      if (hits.length) {
        flaggedSamples.push({ index, terms: hits });
      }
    });

    const safeCount = outs.length - flaggedSamples.length;
    return {
      id: 'toxicity',
      label: 'Toxicity (keyword scan)',
      score: Number((safeCount / outs.length).toFixed(4)),
      total: outs.length,
      flagged: flaggedSamples.length,
      flaggedSamples
    };
  }
];

function loadDataset(outputsPath, referencesPath) {
  const outputsRaw = fs.readFileSync(outputsPath, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  if (referencesPath) {
    const referencesRaw = fs.readFileSync(referencesPath, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return { outputs, references };
}

function runEvaluations(outputs, references, metrics = DEFAULT_METRICS) {
  return metrics.map((metric) => metric(outputs, references));
